resource "aws_cloudwatch_log_group" "this" {
  name              = "/aws/codebuild/${var.pipeline_name}"
  retention_in_days = var.log_retention
  kms_key_id        = var.kms_key
}

resource "aws_codepipeline" "this" {
  name           = var.pipeline_name
  pipeline_type  = "V2"
  role_arn       = aws_iam_role.codepipeline.arn
  execution_mode = var.mode

  artifact_store {
    location = aws_s3_bucket.this.id
    type     = "S3"
  }

  stage {
    name = "Source"
    action {
      name             = "Source"
      category         = "Source"
      owner            = "AWS"
      provider         = var.connection == null ? "CodeCommit" : "CodeStarSourceConnection"
      version          = "1"
      output_artifacts = ["source_output"]
      configuration = {
        RepositoryName       = var.connection == null ? var.repo : null
        FullRepositoryId     = var.connection == null ? null : var.repo
        ConnectionArn        = var.connection
        BranchName           = var.branch
        PollForSourceChanges = var.connection == null ? false : null
        DetectChanges        = var.connection == null ? null : var.detect_changes
      }
    }
  }

  stage {
    name = "Validation"
    dynamic "action" {
      for_each = var.tags == "" ? local.validation_stages : local.conditional_validation_stages
      content {
        name            = action.key
        category        = "Build"
        owner           = "AWS"
        provider        = "CodeBuild"
        input_artifacts = ["source_output"]
        version         = "1"
        configuration = {
          ProjectName = module.validation[action.key].codebuild_project.name
        }
      }
    }
  }

  // parallel
  dynamic "stage" {
    for_each = length(var.sequential) == 0 ? ["plan"] : []
    content {
      name = "Plan"
      dynamic "action" {
        for_each = var.accounts
        content {
          name            = action.key
          category        = "Build"
          owner           = "AWS"
          provider        = "CodeBuild"
          input_artifacts = ["source_output"]
          version         = "1"
          run_order       = 1
          configuration = {
            ProjectName = module.plan.codebuild_project.name
            EnvironmentVariables = jsonencode([
              {
                name  = "WORKSPACE"
                value = action.value
                type  = "PLAINTEXT"
              },
              {
                name  = "ACCOUNT_NAME"
                value = action.key
                type  = "PLAINTEXT"
              },
              {
                name  = "TF_VAR_account_id"
                value = action.value
                type  = "PLAINTEXT"
              },
              {
                name  = "TF_VAR_account_name"
                value = action.key
                type  = "PLAINTEXT"
            }])
          }
        }
      }
      action {
        name      = "Approval"
        category  = "Approval"
        owner     = "AWS"
        provider  = "Manual"
        version   = "1"
        run_order = 2
        configuration = {
          CustomData = "This action will approve the deployment of resources in ${var.pipeline_name}. Please review the plan action before approving."
        }
      }
    }
  }
  dynamic "stage" {
    for_each = length(var.sequential) == 0 ? ["apply"] : []
    content {
      name = "Apply"
      dynamic "action" {
        for_each = var.accounts
        content {
          name            = action.key
          category        = "Build"
          owner           = "AWS"
          provider        = "CodeBuild"
          input_artifacts = ["source_output"]
          version         = "1"
          run_order       = 1
          configuration = {
            ProjectName = module.apply.codebuild_project.name
            EnvironmentVariables = jsonencode([
              {
                name  = "WORKSPACE"
                value = action.value
                type  = "PLAINTEXT"
              },
              {
                name  = "ACCOUNT_NAME"
                value = action.key
                type  = "PLAINTEXT"
              },
              {
                name  = "TF_VAR_account_id"
                value = action.value
                type  = "PLAINTEXT"
              },
              {
                name  = "TF_VAR_account_name"
                value = action.key
                type  = "PLAINTEXT"
            }])
          }
        }
      }
    }
  }

  // sequential
  dynamic "stage" {
    for_each = local.ordered_accounts
    content {
      name = stage.value.name

      action {
        name            = "Plan"
        category        = "Build"
        owner           = "AWS"
        provider        = "CodeBuild"
        input_artifacts = ["source_output"]
        version         = "1"
        run_order       = 1
        configuration = {
          ProjectName = module.plan.codebuild_project.name
          EnvironmentVariables = jsonencode([
            {
              name  = "WORKSPACE"
              value = stage.value.account_id
              type  = "PLAINTEXT"
            },
            {
              name  = "ACCOUNT_NAME"
              value = stage.value.name
              type  = "PLAINTEXT"
            },
            {
              name  = "TF_VAR_account_id"
              value = stage.value.account_id
              type  = "PLAINTEXT"
            },
            {
              name  = "TF_VAR_account_name"
              value = stage.value.name
              type  = "PLAINTEXT"
          }])
        }
      }

      action {
        name      = "Approval"
        category  = "Approval"
        owner     = "AWS"
        provider  = "Manual"
        version   = "1"
        run_order = 2
        configuration = {
          CustomData = "This action will approve the deployment of resources in ${var.pipeline_name}. Please review the plan action before approving."
        }
      }

      action {
        name            = "Apply"
        category        = "Build"
        owner           = "AWS"
        provider        = "CodeBuild"
        input_artifacts = ["source_output"]
        version         = "1"
        run_order       = 3
        configuration = {
          ProjectName = module.apply.codebuild_project.name
          EnvironmentVariables = jsonencode([
            {
              name  = "WORKSPACE"
              value = stage.value.account_id
              type  = "PLAINTEXT"
            },
            {
              name  = "ACCOUNT_NAME"
              value = stage.value.name
              type  = "PLAINTEXT"
            },
            {
              name  = "TF_VAR_account_id"
              value = stage.value.account_id
              type  = "PLAINTEXT"
            },
            {
              name  = "TF_VAR_account_name"
              value = stage.value.name
              type  = "PLAINTEXT"
          }])
        }
      }
    }
  }

}

resource "aws_codebuild_project" "this" {
  name          = var.codebuild_name
  build_timeout = var.build_timeout
  service_role  = var.codebuild_role

  artifacts {
    type = "CODEPIPELINE"
  }

  environment {
    compute_type = "BUILD_GENERAL1_SMALL"
    image        = var.image
    type         = "LINUX_CONTAINER"

    dynamic "environment_variable" {
      for_each = var.environment_variables
      content {
        name  = environment_variable.key
        value = environment_variable.value
      }
    }
  }

  logs_config {
    cloudwatch_logs {
      group_name  = var.log_group
      stream_name = var.codebuild_name
    }
  }

  source {
    type                = "CODEPIPELINE"
    buildspec           = var.build_spec
    git_clone_depth     = 0
    insecure_ssl        = false
    report_build_status = false
  }

  dynamic "vpc_config" {
    for_each = var.vpc == null ? [] : [var.vpc]
    content {
      vpc_id             = vpc_config.value.vpc_id
      subnets            = vpc_config.value.subnets
      security_group_ids = vpc_config.value.security_group_ids
    }
  }
}

