resource "aws_s3_bucket_lifecycle_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    status = "Enabled"
    id     = "${var.artifact_retention}-days"
    filter {
      prefix = ""
    }
    expiration {
      days = var.artifact_retention
    }

  }
}

